/**
 * assertEnvOnBoot.ts — точка, в которой проверка окружения СРАБАТЫВАЕТ.
 *
 * ЗАЧЕМ ОТДЕЛЬНЫЙ ФАЙЛ, А НЕ ВЫЗОВ В `server.ts`
 * В ES-модулях тело модуля выполняется ПОСЛЕ вычисления всех его импортов.
 * `server.ts` импортирует маршруты, маршруты тянут `db/client.js`, а тот бросает
 * прямо на импорте (`db/client.ts:27`, вызов на `:43`). Любой вызов, записанный
 * в теле `server.ts`, опоздал бы: владелец системы увидел бы сообщение про
 * `DATABASE_URL` вместо полного списка незаданных переменных.
 *
 * Поэтому проверка оформлена как ПОБОЧНЫЙ ЭФФЕКТ ИМПОРТА и подключается в
 * `server.ts` раньше всех прочих импортов проекта. Тогда её тело выполняется
 * первым — до `db/client.js` и до фабрики приложения.
 *
 * Разделение на два файла тоже намеренное. `requiredEnv.ts` остаётся ЧИСТЫМ:
 * его можно импортировать из гейта `scripts/check-env-contract.mjs` и из тестов,
 * не останавливая процесс. Побочный эффект живёт только здесь.
 *
 * Граф импортов этого файла обязан оставаться свободным от `db/**`, `routes/**`
 * и `services/**` — иначе порядок нарушится и проверка снова опоздает. Это
 * условие проверяется машинно, в `scripts/check-env-contract.mjs`.
 */

import { loadAdditionalServerEnv } from "./loadServerEnv.js";
import { assertRequiredEnv } from "./requiredEnv.js";

/*
 * Файлы окружения читаются до проверки: иначе значения из `.env` в корне
 * репозитория ещё не в `process.env`, и проверка отвергнет полностью настроенное
 * развёртывание. Тот же загрузчик вызывает `db/client.ts:14`, повторный вызов
 * безопасен — значения только дозаписываются, уже заданные не перетираются.
 */
loadAdditionalServerEnv();
assertRequiredEnv();
